window.__saqPaperQuestions("2023-1-st-george",[{"number":1,"title":"","stemText":"An 18-year-old man presents with facial pain following an altercation outside a kebab shop. The triage nurse has ordered an OPG :","parts":[{"id":"a","label":"Part A","prompt":"List (3) pertinent abnormalities on this X-ray. (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"List (5) relevant findings you would seek on clinical examination based on the X-ray. (5 marks) 1. 2. 3. 4. 5. - 1 -"},{"id":"c","label":"Part C","prompt":"State (4) key steps in your management of this patient. (4 marks) 1. 2. 3. 4. - 2 -"}],"propPages":["asset:imgceba74814d13550274"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Displaced fracture through right body of the mandible</div><div class=\"answer-line\">• Two-part fracture through the angle of the mandible on the left</div><div class=\"answer-line\">• Body of mandible fracture extends through alveolar process and second premolar</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• <strong>Signs concerning for potential airway obstruction</strong> : eg floor of mouth haematoma,</div><div class=\"answer-line\">bleeding, bony instability, swelling and prolapse of oral structures</div><div class=\"answer-line\">• Open fracture</div><div class=\"answer-line\">• Malocclusion/asymmetry</div><div class=\"answer-line\">• Loose/missing teeth</div><div class=\"answer-line\">• Infra-alveolar nerve paraesthesia</div><div class=\"answer-line\">• Degree of mouth opening / trismus</div><div class=\"answer-line\">SGH Trial Fellowship Exam 2023.1</div><div class=\"answer-line\">ANSWERS</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Analgesia (sensible dose/route), antiemetic (dose/route), Barton’s bandage</div><div class=\"answer-line\">• Tooth splinting if mobile</div><div class=\"answer-line\">• IV antibiotics Benzylpenicillin/Cephazolin and + Clindamycin (effective against Strep</div><div class=\"answer-line\">and other oral flora), ADT if needed</div><div class=\"answer-line\">• Admit NBM/IVF pending Max-Facs input for repair</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A nurse has asked you to check the position of this NGT on chest X-ray, inserted by one of your medical students :","parts":[{"id":"a","label":"Part A","prompt":"List (3) relevant findings on this image. (3 marks) 1. 2. 3. - 3 -"},{"id":"b","label":"Part B","prompt":"List (3) immediate clinical actions you would take. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"Outline (6) steps you would take in managing this incident. (6 marks) 1. 2. 3. 4. 5. 6. - 4 -"}],"propPages":["asset:img3fddf3b8dfb5295430"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>1. </strong>NGT has gone down R main bronchus</div><div class=\"answer-line\"><strong>2. </strong>Iatrogenic R-sided pneumothorax</div><div class=\"answer-line\"><strong>3. </strong>R basal opacification – unlikely to be fluid as would expect horizontal air-fluid</div><div class=\"answer-line\">interface</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>1. </strong>Immediate removal of misplaced NGT</div><div class=\"answer-line\"><strong>2. </strong>Supportive : ensure patient clinically stable, provide oxygen and analgesia</div><div class=\"answer-line\"><strong>3. </strong>Insert R small-bore ICC to treat iatrogenic injury<strong> </strong></div><div class=\"answer-line\">SGH Trial Fellowship Exam 2023.1</div><div class=\"answer-line\">ANSWERS</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>1. </strong><strong>Open disclosure</strong> of event to patient / relatives</div><div class=\"answer-line\"><strong>2. </strong><strong>Document</strong> the incident and discussion with patient</div><div class=\"answer-line\"><strong>3. </strong><strong>Notify incident</strong> via hospital’s Incident Management Database</div><div class=\"answer-line\"><strong>4. </strong><strong>Counsel / debrief</strong> the student and the supervising RN / MO</div><div class=\"answer-line\"><strong>5. </strong>Notify student’s clinical supervisor and review policy/procedure for clinical</div><div class=\"answer-line\">supervision of medical students</div><div class=\"answer-line\"><strong>6. </strong>Refer for review and education via M+M</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 3-month-old child presents with poor feeding and tachypnoea.\nAn ECG has been performed for tachycardia :","parts":[{"id":"a","label":"Part A","prompt":"Describe the ECG. (3 marks)"},{"id":"b","label":"Part B","prompt":"List (4) differential diagnoses for the ECG. (2 marks) 1. 2. 3. 4. - 5 -"},{"id":"c","label":"Part C","prompt":"Outline your approach to managing this arrhythmia. (7 marks) 1. 2. 3. 4. 5. 6. 7. - 6 -"}],"propPages":["asset:imgd35546c01fa6797bd0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">SGH Trial Fellowship Exam 2023.1</div><div class=\"answer-line\">ANSWERS</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Ques</strong><strong>Ɵon 3 (12 marks)  </strong></div><div class=\"answer-line\">A 3-month-old child presents with poor feeding and tachypnoea.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Answer : </strong>https://vimeo.com/811180697/a1a5067d2a</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 32-year-old female is brought into the ED by ambulance. She had been found in an alley\nintoxicated and agitated, informing staff that she needs to find her husband who had left her in the street because they had had a fight. You note multiple bruises on her upper arm in keeping with finger marks.","parts":[{"id":"a","label":"Part A","prompt":"List the (4) components of the HITS tool for intimate partner violence screening. (2 marks) How often does your partner...? 2. 3. 4."},{"id":"b","label":"Part B","prompt":"Aside from women, list (6) cohorts of people who are most at risk of domestic violence. (6 marks) 1. 2. 3. 4. 5. 6."},{"id":"c","label":"Part C","prompt":"List (4) circumstances/behaviours that constitute a high risk (increased likelihood of death) to the victim. (4 marks) 1. 2. 3. 4. - 7 -"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Physically HURT you</div><div class=\"answer-line\"><strong>2. </strong>INSULT or talk down to you</div><div class=\"answer-line\"><strong>3. </strong>THREATEN you with harm</div><div class=\"answer-line\"><strong>4. </strong>SCREAM or curse at you</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>1. </strong>People identifying as LGBTQIA+</div><div class=\"answer-line\"><strong>2. </strong>People living with a disability</div><div class=\"answer-line\"><strong>3. </strong>Children</div><div class=\"answer-line\"><strong>4. </strong>Older persons</div><div class=\"answer-line\"><strong>5. </strong>Aboriginal and Torres Strait Islander peoples</div><div class=\"answer-line\"><strong>6. </strong>Culturally and linguistically diverse communities (CALD)</div><div class=\"answer-line\">People in rural and remote Australia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>1. </strong>New pregnancy</div><div class=\"answer-line\"><strong>2. </strong>Recent or planned separation</div><div class=\"answer-line\"><strong>3. </strong>Non-fatal strangulation</div><div class=\"answer-line\"><strong>4. </strong>Harm to pets</div><div class=\"answer-line\">Threats to kill, access to weapons</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false,"investigationTables":[{"id":"investigation-1","title":"Blood results","headers":["Test","Result","Reference Range"],"rows":[["Sodium","133","135-145 mmol/L"],["Potassium","8.2","3.5-5.2 mmol/L"],["Chloride","104","95-110 mmol/L"],["Calcium Ionised","0.84","0.95-1.50 mmol/L"],["Blood Glucose","7.2","3.9-6.1 mmol/L"],["Blood Lactate","3.8","0.2-2.0 mmol/L"],["WCC","344.13","6.5-17.5 x10^9/L"],["Hb","64","95-135 g/L"],["PLT","33","150-450 x10^9/L"],["HCT","0.178","0.29-0.41 L/L"],["MCV","104.7","72-82 fL"],["RCC","1.70","4.5-6.5 x10^12/L"]]}]},{"number":5,"title":"","stemText":"A 64-year-old female is brought to ED by ambulance with an altered conscious state aŌer a\nseizure. She was initially unresponsive on scene but now responds to painful stimuli. Her ABG is provided below :\n\npH\n7.32\n\nNa\n112\n\nPCO2 31\n\nK\n4.1\n\nPO2\n110 (FiO2 21%)\n\nCl\n\nBE\n- 6.0 Gluc 7.0\n\nHCO3 17\n\nUrea 3.0\n\nLactate 4.7","parts":[{"id":"a","label":"Part A","prompt":"Comment on (3) relevant abnormalities. (3 marks) 1. 2. 3. - 8 -"},{"id":"b","label":"Part B","prompt":"Complete the table below providing : (3) categories of hyponatraemia relevant to this patient and (2) plausible differential diagnoses for each category (= 6 marks total) Category of Differential Diagnoses Hyponatraemia The patient commences seizing again."},{"id":"c","label":"Part C","prompt":"Outline your immediate actions. (3 marks) 1. 2. 3. - 9 -"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Critical hyponatraemia of 112 = likely cause for seizure</td></tr><tr><td><strong>2. </strong></td><td>Low serum osmolality = (2x112+7+3 = 234) c/w hypotonic hyponatraemia</td></tr><tr><td><strong>3. </strong></td><td>Mild HAGMA (lactic) with resp compensation – c/w seizure</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td></tr><tr><td colspan=\"2\"><strong>b)</strong><strong> </strong><strong>Complete the table below providing :  </strong></td></tr><tr><td colspan=\"2\"><strong>(3) categories of hyponatraemia relevant to this pa</strong><strong>Ɵent and  </strong></td></tr><tr><td colspan=\"2\"><strong>(2) plausible diﬀeren</strong><strong>Ɵal diagnoses for each category  </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Hypovolaemic</td><td>Renal losses: diuretics, nephropathy.</td></tr><tr><td>Addison’s NOT likely given K and glucose</td><td></td></tr><tr><td>Extra-renal losses: D+V, sweating (heat exhaustion)</td><td></td></tr><tr><td>Euvolaemic</td><td>SIADH: drugs (MDMA), meds (SSRIs), brain/lung pathology</td></tr><tr><td>Water intoxication, e.g. psychogenic polydipsia</td><td></td></tr><tr><td>Hypervolaemic</td><td>CCF</td></tr><tr><td>Liver failure/nephrotic syndrome/hypoalbuminaemia</td><td></td></tr><tr><td>The paƟent commences seizing again.</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Support airway and breathing: provide O2, airway positioning/adjuncts as required</div><div class=\"answer-line\"><strong>2. </strong></div><div class=\"answer-line\"><strong>Terminate seizure : hypertonic saline</strong>: 100ml bolus of 3%; may be repeated x 2 (aim</div><div class=\"answer-line\">to correct Na by &lt;6mmol/L in 6hrs)</div><div class=\"answer-line\"><strong>3. </strong></div><div class=\"answer-line\">Consider IV midazolam bolus and prepare for intubation if no response to HS</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 72-year-old man from home with his wife, is brought in by ambulance aŌer a fall. He reports losing balance and falling forward, hiƫng his head on a window-sill then landing prone on the ground. He has full recall of events and complains of neck pain. Only past medical history is early Parkinsons Disease. On brief initial examination his vitals are unremarkable and there does not currently appear to be any significant neuro deficit. He is immobilised in a hard C-spine collar. You arrange urgent CT brain and C-spine, a section of which shown below : This appears to be the only sequelae of trauma on examination and relevant imaging. - 10 -","parts":[{"id":"a","label":"Part A","prompt":"Complete the table listing (6) specific complications you might anticipate from this injury and state how you would mitigate / manage each if required. Give drug doses and endpoints where relevant. (12 marks) Complication Management - 11 -"}],"propPages":["asset:imgd7f3ed2f4e69586f50"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>Worsening prevertebral </strong></td><td>Careful emergent intubation, ideally fibreoptic</td></tr><tr><td><strong>oedema/hematoma occluding airway </strong></td><td>(but shown to be safe with VL), RSI with</td></tr><tr><td colspan=\"2\">MILS/bougie/most experienced operator</td></tr><tr><td><strong>Respiratory failure</strong> – C2 high risk<strong> </strong></td><td>Intubation (as above) if VC &lt; 30% predicted,</td></tr><tr><td colspan=\"2\">poor cough – oxygenation and ventilation to</td></tr><tr><td colspan=\"2\">normoxia/normocapnia</td></tr><tr><td><strong>Neurogenic shock</strong> – injury above T6</td><td>Art line, judicious fluid resus, early</td></tr><tr><td colspan=\"2\">vasopressor infusion (noradrenaline) titrated</td></tr><tr><td colspan=\"2\">to MAP &gt;85-90mmHg, (atropine for</td></tr><tr><td colspan=\"2\">bradycardia to HR &gt; 60bpm if BP inadequate)</td></tr><tr><td><strong>Cervical myelopathy / cord injury</strong> from</td><td>Appropriate C-spine immobilisation (Phile,</td></tr><tr><td>vertebral compression</td><td>Miami J, Aspen) with strict spinal precautions</td></tr><tr><td colspan=\"2\">(entire spine), careful logroll</td></tr><tr><td>Pressure areas</td><td>Q2H repositioning (air mattress)</td></tr><tr><td>Urinary retention</td><td>IDC insertion</td></tr><tr><td>Aspiration due to gastroparesis, reduced</td><td>Early NGT insertion, NBM</td></tr><tr><td colspan=\"2\">GOS tone</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"An 8-year-old boy with Down Syndrome was playing with his siblings in the yard earlier in the aŌernoon when he tripped and fell, striking his forehead. He is brought in by his parents complaining of a headache and neck pain. You notice he is holding his head in rightward rotation and refusing to move it.","parts":[{"id":"a","label":"Part A","prompt":"What are the (3) main features of torticollis? (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"List (5) differential diagnoses for torticollis in children. (5 marks) 1. 2. 3. 4. 5."},{"id":"c","label":"Part C","prompt":"Why might this child be more susceptible to torticollis? (1 mark)"},{"id":"d","label":"Part D","prompt":"List (3) indications for undertaking CT scanning in a paediatric patient presenting with torticollis. (3 marks) 1. 2. 3. - 12 -"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• <span class=\"answer-source-red\">  </span>Chin points away from contracted muscle</div><div class=\"answer-line\">•   Contracted sternocleidomastoid muscle</div><div class=\"answer-line\">•   Head tilted toward affected muscle</div><div class=\"answer-line\">•   Limited passive ROM</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Trauma</td><td>Fractures</td></tr><tr><td>-</td><td>Occipital condyle fracture / dislocation</td></tr><tr><td>-</td><td>Clavicular</td></tr><tr><td>-</td><td>Cervical spine vertebrae</td></tr><tr><td colspan=\"2\">Atlantoaxial rotatory fixation</td></tr><tr><td colspan=\"2\">Posterior fossa / spinal epidural haematoma</td></tr><tr><td>Infection</td><td>Head and neck infections</td></tr><tr><td colspan=\"2\">– esp retropharyngeal abscess / cervical adenitis</td></tr><tr><td colspan=\"2\">Spinal infections</td></tr><tr><td>-</td><td>Discitis or osteomyelitis</td></tr><tr><td colspan=\"2\">CNS</td></tr><tr><td colspan=\"2\">Upper lobe chest</td></tr><tr><td>Inflammation</td><td>Juvenile rheumatoid arthritis</td></tr><tr><td>Neoplasia</td><td>CNS tumour (classically CN4 – not true torticollis)</td></tr><tr><td colspan=\"2\">Neck tumours</td></tr><tr><td>Miscellaneous</td><td>Vascular abnormalities, acute dystonic reactions</td></tr><tr><td colspan=\"2\">Muscular torƟcollis = diagnosis of exclusion</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td></tr><tr><td colspan=\"2\">Always think of ocular torƟcollis  ƟlƟng of head to compensate for oculomotor</td></tr><tr><td colspan=\"2\">impairment</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Children with Down Syndrome higher risk for atlantoaxial dislocaƟon due to laxity of</div><div class=\"answer-line\">transverse ligament</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Associated neurological dysfunction</div><div class=\"answer-line\">• Severe pain not alleviated by analgesia or relaxants</div><div class=\"answer-line\">• Bony anomaly suspected clinically or abnormal cervical Xray</div><div class=\"answer-line\">• Suspicion of retropharyngeal abscess</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 37-year-old female with a history of alcohol misuse disorder presents to your urban\nEmergency Department with a 4-day history of generalised severe abdominal pain, intractable nausea and vomiting (most recently dark brown material). She tells you she has a history of alcohol withdrawal seizures and alleges that she has not eaten or drunken anything per orally\nin the past 4 days. She is drowsy and looks unwell from the end of the bed.\nHer vital signs are as follows : Temp 37.9°C HR 130 BP 87/55 RR 28\nHer venous blood gas is shown: Other relevant blood tests:\n\npH\n7.26\n\nUrea\n\npCO2\n\nCreatinine\n125\n\nHCO3\n\nHb\n101 Bilirubin Sodium 123 GGT 1010\n\nK\n2.9 ALP 107\n\nCl\nAST 133 Ca 0.93 ALT 101 Glu 13.4 Lipase 1150 Lact 3.0","parts":[{"id":"a","label":"Part A","prompt":"In addition to pancreatitis, list (4) key diagnoses to consider in this patient. (4 marks) 1. 2. 3. 4. - 13 -"},{"id":"b","label":"Part B","prompt":"From the provided values please calculate the : (3 marks) Anion Gap Delta Ratio Expected PCO2"},{"id":"c","label":"Part C","prompt":"Summarise the acid-base disturbance (1 mark) A CT abdomen is performed :"},{"id":"d","label":"Part D","prompt":"State the important finding. (1 mark)"},{"id":"e","label":"Part E","prompt":"List (3) other potential acute local complications. (3 marks) 1. 2. 3."},{"id":"f","label":"Part F","prompt":"Without knowing any further information, outline (6) key management steps for this patient (6 marks) 1. 2. 3. 4. 5. 6."}],"propPages":["asset:imge4949af5d3f03f3304"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Upper GI haemorrhage – accept variceal bleed, MW tear, anything else reasonable</div><div class=\"answer-line\">(ulcer, gastric erosion etc)</div><div class=\"answer-line\">• Sepsis – biliary, CNS</div><div class=\"answer-line\">• Alcohol withdrawal</div><div class=\"answer-line\">• Cerebral haemorrhage (spontaneous, traumatic)</div><div class=\"answer-line\">• Anything else reasonable – TTP, other surgical pathology</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1) Anion Gap = Na – (HCO3 + Cl) = 27</div><div class=\"answer-line\">2) Delta Ratio = (27-12)/(24-16) = 15/8 = 1.87</div><div class=\"answer-line\">3) Expected CO2 = (HCO3 x 1.5) + 8 = 24 + 8 = 32</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pure moderate HAGMA with appropriate respiratory compensaƟon</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">HypoatuenaƟon in the tail of pancreas with associated peripancreaƟc stranding</div><div class=\"answer-line\">consistent with pancreaƟc necrosis.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Pancreatic pseudocyst</div><div class=\"answer-line\">• Pancreatic abscess</div><div class=\"answer-line\">• Fistulae</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">• Volume repletion : 500mL boluses of crystalloid to MAP &gt; 65, improvement in</div><div class=\"answer-line\">tachycardia and end-organ perfusion, then ongoing crystalloid infusion to maintain</div><div class=\"answer-line\">UO &gt; 0.5mL/kg/hr</div><div class=\"answer-line\">• Antibiotics - ceftriaxone 2g IV (sepsis cover, variceal bleed) + metronidazole 500mg</div><div class=\"answer-line\">IV if concern for GI perforation</div><div class=\"answer-line\">• Management of potential alcohol withdrawal : AWS +/- benzodiazepine, thiamine</div><div class=\"answer-line\">500mg IV</div><div class=\"answer-line\">• Symptomatic management: NBM +/- NGT, aggressive analgesia, anti-emesis (drugs</div><div class=\"answer-line\">and doses), IDC and careful fluid balance</div><div class=\"answer-line\">• Electrolyte replacement : Ca and K with Mg</div><div class=\"answer-line\">• Accept octreotide, IV PPI +/- infusion</div><div class=\"answer-line\">• Referral to surgeon/gastro and ICU for ongoing management</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are looking aŌer a 10-week-old male infant who presented febrile and listless. Urgent blood results have been called through from the lab and are shown below : Reference Range Sodium 133 135-145 mmol/L Potassium 8.2 3.5-5.2 mmol/L Chloride 104 95-110 mmol/L Calcium Ionised 0.84 0.95-1.50 mmol/L Blood Glucose 7.2 3.9-6.1 mmol/L Blood Lactate 3.8 0.2-2.0 mmol/L\n\nWCC\n344.13 6.5-17.5 x10^9/L\n\nHb\n95-135 g/L PLT 150-450 x10^9/L HCT 0.178 0.29-0.41 L/L MCV 104.7 72-82 fL RCC 1.70 4.5-6.5 x10^12/L","parts":[{"id":"a","label":"Part A","prompt":"Provide an explanation for (5) abnormalities (other than K+) in these results. (5 marks) Abnormality Explanation/Cause"},{"id":"b","label":"Part B","prompt":"List a possible complication related to (4) of the abnormal blood results (4 marks) Abnormal value Complication"},{"id":"c","label":"Part C","prompt":"What is the most likely diagnosis? (1 mark) An ECG is performed and shown below :"},{"id":"d","label":"Part D","prompt":"List (4) normal infant ECG parameters that are different from adults. (4 marks) 1. 2. 3. 4."},{"id":"e","label":"Part E","prompt":"Outline your approach to his K+ result. (4 marks) 1. 2. 3. 4."}],"propPages":["asset:imgaf8085effd59fa1517"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>WCC 344</td><td>Acute Leukaemia</td></tr><tr><td>Hb 64</td><td>Marrow invasion by blasts = decreased producƟon. Physiological +/-</td></tr><tr><td colspan=\"2\">infecƟve haemolysis</td></tr><tr><td>Plt 33</td><td>Marrow invasion by blasts = decreased producƟon. ? Splenomegaly</td></tr><tr><td colspan=\"2\">with sequestraƟon</td></tr><tr><td>Lactate 3.8</td><td>SepƟc hypoperfusion, diminished oxygen carrying capacity as</td></tr><tr><td colspan=\"2\">anaemic</td></tr><tr><td>Ca 0.84</td><td>Possible tumour lysis causing phosphate release and Ca++</td></tr><tr><td colspan=\"2\">precipiƟon</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>WCC 344</td><td>Tumour lysis, hyperviscosity syndrome</td></tr><tr><td>Hb 64</td><td>Poor oxygen carrying capacity</td></tr><tr><td>Plt 33</td><td>Petechiae, bleeding</td></tr><tr><td>K+ 8.2</td><td>Cardiac arrhythmia, arrest</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Acute Lymphocytic Leukaemia</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">HR 120-160</td></tr><tr><td><strong>2. </strong></td><td>Right Ventricular dominance R waves V1-V6</td></tr><tr><td><strong>3. </strong></td><td>Right axis (up to 180 degrees)</td></tr><tr><td><strong>4. </strong></td><td>PR, QRS max shorter than adult max of 0.2 and 0.11 respecƟvely</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">K+ 8.2 – ? tumour lysis ? pseudohyperkalaemia (NB White cell haemolysis doesn’t</td></tr><tr><td colspan=\"2\">produce haem pigment so not picked up by spectrophotometry)</td></tr><tr><td colspan=\"2\">ECG not c/w hyperkalaemia – explanaƟon – slow rise of K+ or in vitro</td></tr><tr><td colspan=\"2\">acquisiƟon/centrifugaƟon haemolysis</td></tr><tr><td><strong>2. </strong></td><td>Approach – conƟnue to monitor ECG for hyperkalaemic changes as child at risk of</td></tr><tr><td colspan=\"2\">tumour lysis and hyperK</td></tr><tr><td><strong>3. </strong></td><td>Minimise acquisiƟon/centrifugaƟon haemolysis with free ﬂowing VBG</td></tr><tr><td><strong>4. </strong></td><td>If VBG K+ - &lt; 5.5 – in vitro haemolysis, no acute Rx</td></tr><tr><td colspan=\"2\">If VBG K+ &gt; 5.5, normal ECG – Rx with K+ shiŌ – rehydrate, insulin/dextrose/</td></tr><tr><td colspan=\"2\">NaHCO3</td></tr><tr><td colspan=\"2\">If VBG K+ &gt; 5.5 and ECG changes – as above, but consider ca gluconate – relaƟve CI</td></tr><tr><td colspan=\"2\">with tumour lysis</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"You are the consultant working in a mixed Emergency Dept when the triage nurse alerts you\nto the arrival of a 15-month-old boy with lethargy & vomiting.\nThe child was found in the back seat of a car at the local RSL club car park. Outside\ntemperature is 38°C.\nThe child is moved straight into the resuscitation area and monitoring is placed. Vital signs are recorded as follows\n\nTemp (tympanic)\n40.6C\n\nHR\n170bpm\n\nBP\n60/40\n\nRR\n\nSaO2\n90% on RA P on AVPU scale","parts":[{"id":"a","label":"Part A","prompt":"List (2) physiological characteristics of children which make them more susceptible to heat-related illness compared with adults. (2 marks) 1. 2. Intravenous access is obtained and initial resuscitation has commenced."},{"id":"b","label":"Part B","prompt":"Prioritise a list of (3) methods you would use to rapidly cool this child. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"In addition to the above cooling measures, outline (4) further actions in your acute resuscitation plan. (4 marks) 1. 2. 3. 4. As you commence cooling measures, the child starts to have a generalised seizure."},{"id":"d","label":"Part D","prompt":"In addition to heatstroke, list (3) possible causes and a specific treatment for each. (3 marks) Cause of seizure Treatment"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Higher basal metabolic rate than adults -&gt; produce more heat</div><div class=\"answer-line\">Higher surface area : mass raƟo resulƟng in greater heat absorpƟon in hot environments</div><div class=\"answer-line\">Smaller absolute blood volume resulƟng in lower blood-born heat dissipaƟon from core</div><div class=\"answer-line\">to surface</div><div class=\"answer-line\">Lower rate of sweaƟng than adults / begin sweaƟng at higher temperatures</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>3. </strong>Ice packs to neck, groin and axillae (minimise shivering with BZD)<strong> </strong></div><div class=\"answer-line\"><strong>4. </strong>Cool IVF 4°C<strong> </strong></div><div class=\"answer-line\"><em>NOT antipyretics, evidence for invasive measures lacking, cold immersion impracticable </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>3. </strong>Intubate, sedate and paralyse if rectal temp &gt;40 degC despite initial cooling measures</div><div class=\"answer-line\"><strong>4. </strong>Seek and treat complications eg pulmonary oedema, DIC, AKI</div><div class=\"answer-line\">Ensure child on continuous cardiac and core rectal temperature monitoring, IDC</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>IV bolus 2mL/kg 10% dextrose </strong></td><td></td></tr><tr><td>Hyponatraemia</td><td>IV bolus 3mL/kg 3% saline (repeat 2x until</td></tr><tr><td>cessation of seizure</td><td></td></tr><tr><td>Febrile convulsion</td><td>IV midazolam 0.15mg/kg</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td></tr><tr><td>Supportive, ongoing cooling</td><td></td></tr><tr><td>Cerebral oedema</td><td>IV midazolam 0.15mg/kg</td></tr><tr><td>Nurse 30° head up</td><td></td></tr><tr><td>Pre-existing seizure disorder</td><td>IV midazolam 0.15mg/kg</td></tr><tr><td>IV phenytoin/leviteracitam</td><td></td></tr><tr><td>Cerebral haemorrhage 2° to DIC</td><td>Neuroprotective measures and neuroSx</td></tr><tr><td>referral</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 74-year-old man is brought to ED by ambulance aŌer a collapse at home.\n\nVital signs are as follows :\n\nBP\n90/50\n\nSaO2\n95% RA\n\nRR\n\nTemp\n36°C\n\nBSL\n7.0 His ECG is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (5) pertinent features on the ECG (5 marks) and give your overall interpretation of the ECG changes (1 mark) 1. 2. 3. 4. 5. Interpretation : Prior to initiating any medical management, the patient indicates that he wishes to self- discharge against medical advice."},{"id":"b","label":"Part B","prompt":"What would you say to him regarding this decision? (1 mark)"},{"id":"c","label":"Part C","prompt":"List (5) elements of capacity/competence that you would assess in this man regarding his decision to self-discharge. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:imgb6491f3159d0c5fe28"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Sinus rhythm ~120bpm with associated <strong>high-grade AV block</strong> (presumably the reason</div><div class=\"answer-line\">for PPM)</div><div class=\"answer-line\">• <strong>Pacing spikes</strong> follow each native P wave</div><div class=\"answer-line\">• Approximately half the pacing spikes are followed by a paced QRS</div><div class=\"answer-line\">• <strong>Approximately half the pacing spikes are not followed by a paced QRS </strong></div><div class=\"answer-line\">• Resultant ventricular rate is ~60. No obvious ischaemic changes.</div><div class=\"answer-line\">SGH Trial Fellowship Exam 2023.1</div><div class=\"answer-line\">ANSWERS</div><div class=\"answer-line\"><strong>Interpreta</strong><strong>Ɵon :</strong><em> </em></div><div class=\"answer-line\">Paced rhythm with intermitent failure to capture</div><div class=\"answer-line\">Prior to iniƟaƟng any medical management, the paƟent indicates that he wishes to self-</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">High risk of cardiac arrest, may die if he self-discharges home</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Ability to <strong>understand</strong> relevant information</div><div class=\"answer-line\">• Ability to <strong>retain</strong> information relevant to the decision</div><div class=\"answer-line\">• Ability to appreciate the situation and its <strong>consequences</strong></div><div class=\"answer-line\">• Ability to <strong>weigh up</strong> the information in a rational fashion</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 32-year-old lady presents with bloating, low abdominal pain and shortness of breath on\nminimal exertion. She is on the IVF program, had egg retrieval 13 days ago and transfer of\nan embryo 7 days ago.\nShe has been advised to present to emergency due to possible ovarian hyperstimulation syndrome (OHSS) You decide to investigate with bedside ultrasound and images are shown below : RUQ LUQ","parts":[{"id":"a","label":"Part A","prompt":"List (2) features of ovarian hyperstimulation syndrome demonstrated in the ultrasound images (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"List (4) important complications of critical OHSS and state how they may be managed\n• r prevented. (8 marks)\nComplication Prevention or Management 1. 2. 3. 4."}],"propPages":["asset:img04d827e143aa33c510","asset:img4aada0477c9af21a56"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>i.</td><td>Bilateral pleural effusions (spine sign bilaterally)</td></tr><tr><td>ii.</td><td>Ascites  (mild on these images)</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>1. </strong>Oliguric renal failure</td><td>Maintain intravascular volume, strict fluid balance</td></tr><tr><td colspan=\"2\">with IDC, avoid diuretics and nephrotoxins</td></tr><tr><td><strong>2.  </strong><strong>Ovarian torsion </strong></td><td>Prompt recognition in any patient with severe</td></tr><tr><td colspan=\"2\">abdominal pain, early O+G referral for surgical</td></tr><tr><td colspan=\"2\">management</td></tr><tr><td><strong>3. </strong>Tense ascites or massive</td><td>Drain/paracentesis under ultrasound guidance</td></tr><tr><td colspan=\"2\">hydrothorax or pericardial</td></tr><tr><td colspan=\"2\">effusion</td></tr><tr><td><strong>4. </strong><strong>Thromboembolism (arterial </strong></td><td>TEDS/clexane</td></tr><tr><td><strong>and venous) </strong></td><td>Therapeutic anticoagulation if confirmed</td></tr><tr><td colspan=\"2\">Electrolyte disturbance :  Monitor and correct hypoNa and hyperK</td></tr><tr><td colspan=\"2\">ARDS : Careful fluid balance, respiratory support as needed, ICU</td></tr><tr><td colspan=\"2\">Bacterial peritonitis (usually if IDC/drain) : 3rd/4th generation cephalosporin + metronidazole</td></tr><tr><td colspan=\"2\">Intractable nausea and vomiting : fluid repletion, antiemetic</td></tr><tr><td colspan=\"2\">Cardiac dysrhythmia : Monitor, correct hypoK/hypoMg</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 7-year-old boy of Filipino descent, who has recently emigrated to Australia, presents with inability to weight bear aŌer a fall onto his leŌ-hand side 2 days ago. He has no medical or surgical history and is otherwise well. He weighs 30kg and is 137cm tall.","parts":[{"id":"b","label":"Part B","prompt":"Identify (3) salient findings on the imaging. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"Name (3) possible conditions underlying this presentation. (3 marks) 1. 2. 3."},{"id":"d","label":"Part D","prompt":"Identify (4) further investigations to perform in ED with brief justification (2 marks) 1. 2. 3. 4."},{"id":"e","label":"Part E","prompt":"Identify (4) pertinent further managements steps for this child (4 marks) 1. 2. 3. 4."}],"propPages":["asset:img5baaa82f0a5c56c74b","asset:img98a5f0e5b79c84a6ca"],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["rays of his pelvis and L knee are shown below :"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Avascular necrosis of femoral head</div><div class=\"answer-line\">• Disruption of Shenton’s line</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Osteopetrosis</div><div class=\"answer-line\">• Ricketts disease (vitamin D deficiency)</div><div class=\"answer-line\">• Paget’s disease</div><div class=\"answer-line\">• Accept osteogenesis imperfecta, malnutrition, non-accidental injury</div><div class=\"answer-line\"><em>Not accepting osteosarcoma, Ewings, disseminated bony malignancy etc </em></div><div class=\"answer-line\">SGH Trial Fellowship Exam 2023.1</div><div class=\"answer-line\">ANSWERS</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Blood test :  FBC, EUC, <strong>CMP</strong>, <strong>LFT (ALP),</strong> <strong>vitamin D</strong>, ESR, 1,25 Dihydroxycolecalciferol</div><div class=\"answer-line\">(must have 2 of 3 in bold for 1 mark)</div><div class=\"answer-line\">• XRs : accept left femur/tib fib XR, CXR (pre op, NAI screening), skeletal survey</div><div class=\"answer-line\">(determine extent of disease, NAI screen, other injuries from fall</div><div class=\"answer-line\">• Any reasonable answer, hesitantly accept CT brain but only if for NAI screening</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• <strong>Analgesia</strong> (PO, IV, FIB block)</div><div class=\"answer-line\">• Bedrest/NWB/keep NBM</div><div class=\"answer-line\">• Orthopaedic and paediatric (endocrine) involvement (for admission)</div><div class=\"answer-line\">• <strong>Social work</strong> (if concerns re: NAI, overseas family – finance/insurance)</div><div class=\"answer-line\">• Anything reasonable</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You are working in a tertiary hospital when a BAT phone is received from an ambulance on its way from the airport. Flanked by the AFP, a Russian diplomat has suddenly become unwell\n• n a flight that was leaving Sydney enroute to Moscow. The plane turned around within 30\nminutes of take-off. He appears to have vomited and has been both incontinent of bladder and bowels. Vitals are as follows:\n\nGCS 13, pinpoint pupils\n\nHR 35\n\nRR 28 (shallow breathing)\n\nSat O2 92% 15L/min NRB\n\nBP 105/60","parts":[{"id":"a","label":"Part A","prompt":"What is the most concerning diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"Outline (3) immediate priorities in managing this patient. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"Give (2) SPECIFIC antidotes, their dose and mechanism of action. (4 marks) 1. 2."},{"id":"d","label":"Part D","prompt":"In addition to the clinical scenario given, list (2) SPECIFIC early complications of this type of poisoning and your management of each. (4 marks) Complication Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Organophosphate poisoning with a nerve agent causing a cholinergic crisis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Personal protection: non rebreathing apparatus and sealed suits if pt not</div><div class=\"answer-line\">decontaminated at the airport otherwise PPE, negative pressure room, educate</div><div class=\"answer-line\">team</div><div class=\"answer-line\">• Resuscitation: O2, IV access, RSI secure airway (rocuronium not suxamethonium),</div><div class=\"answer-line\">ventilatory support</div><div class=\"answer-line\">• Decontamination: all clothing removed and securely packaged for AFP, use towels to</div><div class=\"answer-line\">dab dry secretions, notify HazMat</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Atropine 1-3mg IV, doubling dose q5-10 min : blocks ACh receptors (muscarinic &gt;</div><div class=\"answer-line\">nicotinic).  Endpoint is clearing of bronchial secretions.</div><div class=\"answer-line\">• Pralidoxime 30mg/kg IV over 15-30 min-&gt; 8mg/kg/hr (must be administered within</div><div class=\"answer-line\">minutes to few hours) : reactivates acetylcholinesterase</div><div class=\"answer-line\">SGH Trial Fellowship Exam 2023.1</div><div class=\"answer-line\">ANSWERS</div><div class=\"answer-line\">• Consider neostigmine 1mg IV (anticholinergic agent)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Seizures : IV benzodiazepines, other anticonvulsants less effective but use in</div><div class=\"answer-line\">refractory cases</div><div class=\"answer-line\">QT prolongation and ventricular dysrhythmia : cardioversion as needed, IV MgSO4</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 29-year-old female at 33/40 gestation is brought to your Emergency Department following\nan MVA. Mechanism car vs tree, travelling 50km/hr. She was restrained and airbags deployed and now complains of abdominal pain.","parts":[{"id":"a","label":"Part A","prompt":"Other than MVA what are the (2) other most common causes of trauma in pregnancy? (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"List (5) pregnancy-specific complications of trauma and provide a positive clinical or investigation finding for each (5 marks) Complication Clinical/Investigation Finding You notice a seat-belt bruise across her lower abdomen."},{"id":"c","label":"Part C","prompt":"What is the significance of this? (1 mark)"},{"id":"d","label":"Part D","prompt":"List (4) relevant facts relating to the utility of bedside ultrasound in the assessment of the pregnant trauma patient. (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Falls</div><div class=\"answer-line\">DomesƟc Violence</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Pelvic pain, uterine contractions, PV bleeding,</td><td></td></tr><tr><td><strong>foetal distress on CTG</strong></td><td></td></tr><tr><td>Direct foetal trauma</td><td>No FM/FHB on CTG/US</td></tr><tr><td>Ruptured uterus</td><td><strong>Maternal shock</strong>, palpable foetal parts, difficulty</td></tr><tr><td>defining uterus on palpation, +ve FAST</td><td></td></tr><tr><td>Early labour</td><td>Increasing regularity contraction, cervix &lt;3cm on</td></tr><tr><td>PROM</td><td>Vaginal loss of liquor, confirmed by alkaline by</td></tr><tr><td>nitrazine test (or Amnisure ROM test)</td><td></td></tr><tr><td>Feto-maternal haemorrhage</td><td>Positive Kleihauer test</td></tr><tr><td>Amniotic fluid embolism</td><td>Obstructive shock, signs of right heart strain on</td></tr><tr><td>US/ECG, DIC</td><td></td></tr><tr><td>Placental or umbilical cord laceration</td><td>Positive Kleihauer test</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Incorrect seatbelt placement over abdomen rather than thighs will increase likelihood of</div><div class=\"answer-line\">foetal injury.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Free ﬂuid in the abdomen may indicate blood or liquor from uterine rupture</div><div class=\"answer-line\">Can assess : FHR, acƟvity, presentaƟon/lie, liquor volume, placental posiƟon <em>(accept 2 of </em></div><div class=\"answer-line\"><em>these) </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 68-year-old man is brought into your urban district ED by ambulance having been found\ncollapsed in a shopping centre. On arrival he is motled and agitated with the following obs :\n\nTemp 34.5°C\n\nHR\n130 regular\n\nBP\n78/54\n\nRR\n\nSats\nunrecordable\n\nGCS\nE3V4M6 = 13 Rapid exam reveals clear chest, soŌ non-tender abdomen, unilateral leg swelling. You have no PMHx available at this time other than a history of prostate cancer.","parts":[{"id":"a","label":"Part A","prompt":"Define massive PE. (1 mark)"},{"id":"b","label":"Part B","prompt":"List (4) differentials for tachypnoea and shock with clear chest on examination. (2 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"State (3) findings you might find on bedside cardiac ultrasound in the seƫng of massive PE. (3 marks) 1. 2. 3."},{"id":"d","label":"Part D","prompt":"State your immediate management priorities, including doses and endpoints. (4 marks) 1. 2. 3. 4. Before you even have a chance to initiate your resuscitation plan, the patient goes into cardiac arrest and CPR is commenced."},{"id":"e","label":"Part E","prompt":"Assuming this is secondary to massive PE, what measures additional to usual ACLS are necessary in managing this cardiac arrest? (2 marks) 1. 2."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">PE with haemodynamic compromise with a SBP &lt; 90mmHg for &gt; 15 minutes</div><div class=\"answer-line\">(or profound bradycardia &lt; 40 with signs of shock, sustained SBP drop &gt; 40mmHg</div><div class=\"answer-line\">below baseline if known)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>1. </strong>Pericardial tamponade</div><div class=\"answer-line\"><strong>2. </strong>Sepsis</div><div class=\"answer-line\"><strong>3. </strong>AMI</div><div class=\"answer-line\"><strong>4. </strong>Myocarditis</div><div class=\"answer-line\">SGH Trial Fellowship Exam 2023.1</div><div class=\"answer-line\">ANSWERS</div><div class=\"answer-line\">• DKA<strong> </strong></div><div class=\"answer-line\">• Severe acute blood loss<strong> </strong></div><div class=\"answer-line\">• Salicylate poisoning<strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• <strong>RV dilatation</strong> : diameter &gt; 2.5cm on PLAX view with normal wall thickness</div><div class=\"answer-line\">• Dilated IVC with lack of respiratory collapse</div><div class=\"answer-line\">• Flat intraventricular septum</div><div class=\"answer-line\">• McConnel’s sign – right free ventricle wall is hypokinetic / akinetic but there is</div><div class=\"answer-line\">hyperkinesis or normal movement at the apical segment (<em>can be seen in RV MI as well)</em></div><div class=\"answer-line\">• Clot in transit</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• <strong>Optimise oxygenation</strong> : supplemental O2 titrated to sats 94-98%<strong> </strong></div><div class=\"answer-line\">• Haemodynamic resuscitation :  <strong>fluid conservative approach</strong> as IVF may worsen RV</div><div class=\"answer-line\">dilatation – judicious bolus followed by <strong>early vasopressors </strong>titrate to MAP &gt;65mmHg<strong> </strong></div><div class=\"answer-line\">• <strong>Administration of thrombolysis </strong>(if no contraindications) : for patient &gt;65kg alteplease</div><div class=\"answer-line\">10mg IV bolus over 1-2 minutes followed by 90mg infusion over 2 hours</div><div class=\"answer-line\">• Consider cold sepsis : empiric antibiotics of 2g IV flucloxacillin and 5-7mg/kg gent stat</div><div class=\"answer-line\">dose</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">Alteplase 50mg IV push over 60 seconds</div><div class=\"answer-line\">ii.</div><div class=\"answer-line\">Prolonged CPR – ideally with LUCAS device – up to 1 hour or until ROSC</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 78-year-old female is brought to ED via ambulance from home aŌer a neighbour found her\ncollapsed in the backyard. She is a reclusive hoarder with no known NOK. Neighbours report she rarely seeks medical atention. Her initial vital signs are :\n\nHR\n\nBP\n100/50\n\nGCS\n\nTemp 27°C","parts":[{"id":"a","label":"Part A","prompt":"In addition to environmental exposure, list (6) potential contributing factors to hypothermia in this patient. (6 marks) 1. 2. 3. 4. 5. 6."},{"id":"b","label":"Part B","prompt":"List (6) clinical features of severe hypothermia as per the categories below. (3 marks - 1⁄2 mark each) General Respiratory Cardiovascular CNS Renal GIT"},{"id":"c","label":"Part C","prompt":"Outline (4) techniques you could use in the ED to rewarm the patient. For each give the expected rate of temperature change. (4 marks) Technique Rate of change"},{"id":"d","label":"Part D","prompt":"Outline (5) changes to the ACLS algorithm which need to be made in the patient with severe hypothermia. (5 marks) 1. 2. 3. 4. 5."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Metabolic : <strong>hypothyroidism</strong>, adrenal insuﬃciency</div><div class=\"answer-line\">MalnutriƟon/frailty with low BMI</div><div class=\"answer-line\">Skin : any widespread erythroderma, psoriasis or exfoliaƟve condiƟon</div><div class=\"answer-line\">Psychiatric</div><div class=\"answer-line\">Social isolaƟon</div><div class=\"answer-line\"><strong>b)</strong><strong> </strong><strong>List (6) clinical features of severe hypothermia as per the categories below. (3 marks – </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">mottled skin, no shivering, cyanosis</td></tr><tr><td><strong>Respiratory </strong></td><td>apnoea, crepitations suggestive of pulmonary oedema</td></tr><tr><td><strong>Cardiovascular </strong></td><td>bradycardia, hypotension, thready/absent peripheral pulses</td></tr><tr><td><strong>CNS </strong></td><td>coma, pupillary dilation, decreased deep tendon reflexes</td></tr><tr><td><strong>Renal </strong></td><td>oliguria</td></tr><tr><td><strong>GIT </strong></td><td>decreased bowel sounds</td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Forced air warming blanket</td><td>2°C/hr</td></tr><tr><td>Warmed humidified oxygen</td><td>1-1.5°C/hr</td></tr><tr><td>Body cavity lavage (bladder/gastric/chest)</td><td>3-6°C/hr</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Pulse check for at least 30 seconds (consider US/doppler)</div><div class=\"answer-line\">• Move patient gently if &lt;32° (theoretical risk of triggering VF)</div><div class=\"answer-line\">• No resuscitation drugs &gt;30°</div><div class=\"answer-line\">• Between 30-35°double dose intervals of ACLS drugs</div><div class=\"answer-line\">• 3 stacked shocks initially for VF, then no further shocks until &gt;30°</div><div class=\"answer-line\">• Except in exceptional circumstances, do not cease resuscitation until &gt;32°</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"It is a busy Saturday evening in a tertiary ED where you are working as a junior FACEM. The NUM has received a call from the head of the local ambulance service informing them that a bomb has just gone off at a music concert. They have declared a major incident.","parts":[{"id":"a","label":"Part A","prompt":"Define the term ‘major incident’ when used in a medical context. (2 marks) You will be receiving > 40 casualties who have all sustained blast injuries."},{"id":"b","label":"Part B","prompt":"Complete the table below describing the (4) different categories of blast injuries with an example of each. (8 marks) Mechanism of Injury Example Primary Secondary Tertiary Quaternary"},{"id":"c","label":"Part C","prompt":"In additional to relevant clinical services (ie. blood bank/pathology/radiology/OT staff), list (4) key individuals/services who must also be informed once a major incident such as this has been declared. (4 marks) 1. 2. 3. 4. As the consultant in charge, you are responsible for preparing the department to receive the casualties."},{"id":"d","label":"Part D","prompt":"Outline (4) key components of preparing the department. (4 marks) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A major incident can be deﬁned as any incident where the locaƟon, number, severity or</div><div class=\"answer-line\">type of live casualƟes requires extraordinary resources.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">PTX, hollow viscus perforation, TM</td></tr><tr><td colspan=\"3\">rupture</td></tr><tr><td><strong>Secondary </strong></td><td>Airborne objects eg shrapnel</td><td>Fractures, amputations, penetrating</td></tr><tr><td>causing penetrating trauma</td><td>injuries</td><td></td></tr><tr><td><strong>Tertiary </strong></td><td>From being thrown by blast</td><td>Fractures, head injuries</td></tr><tr><td><strong>Quaternary </strong></td><td>Everything else resultant from</td><td>Burns, asthma attacks, radiation</td></tr><tr><td>blast</td><td>effects</td><td></td></tr><tr><td>SGH Trial Fellowship Exam 2023.1</td><td>ANSWERS</td><td></td></tr><tr><td colspan=\"3\"><strong>c)</strong><strong> </strong><strong>In additional to relevant clinical services (ie. blood bank/pathology/radiology/OT </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Media liaison / public relations</div><div class=\"answer-line\">Security</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>Staﬀ</strong>: allocate roles, form teams, call in extra staﬀ or place on standby</div><div class=\"answer-line\"><strong>Supplies</strong>: disaster packs, labels, equipment (dressings, splints etc), blood products,</div><div class=\"answer-line\">analgesia, IV access etc</div><div class=\"answer-line\"><strong>Space</strong>: move paƟents out of the department, set up triage areas for walking wounded vs</div><div class=\"answer-line\">ambulances, uƟlise other parts of hospital eg outpaƟent clinics and nonclinical areas</div><div class=\"answer-line\"><strong>Systems</strong>: acƟvaƟon of disaster plan including triage system, media and family liaisons</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
